UPDATE memory.skill_drafts d SET status = 'evaluating' WHERE d.id = (SELECT c.id FROM memory.skill_drafts c LEFT JOIN memory.skill_draft_eval_failures f ON f.draft_id = c.id WHERE c.status IN ('draft', 'evaluating') AND (f.draft_id IS NULL OR f.last_failed_at <= now() - interval '1 hour' * (2 ^ f.attempts)) ORDER BY (c.status = 'evaluating') DESC, c.created_at, c.id LIMIT 1 FOR UPDATE OF c SKIP LOCKED) RETURNING d.id, d.project_id, d.folder, d.description, d.skill_md, d.reference_files, d.test_prompts, d.assertions, d.trigger_queries, d.eval_progress
